SELECT json_extract(payload,'$.organization_id') AS organization_id,COUNT(DISTINCT patient) AS patient_count FROM records WHERE stream='labs' AND lower(json_extract(payload,'$.name')) IN ('hba1c','hemoglobin a1c','hemoglobin a1c/hemoglobin.total') AND json_extract(payload,'$.unit')='%' AND json_type(payload,'$.value') IN ('integer','real') AND json_extract(payload,'$.organization_id') IS NOT NULL GROUP BY 1 ORDER BY 1;
